    if len(upper) != len(lower):
        return [row[:] for row in grid]

    out = [row[:] for row in grid]
    max_shift = min(4, w - 1)
    for ur, lr in zip(upper, lower):
        top = {c for c, v in enumerate(grid[ur]) if v != background}
        bot = {c for c, v in enumerate(grid[lr]) if v != background}

        # Align the lower row to the upper row: lower column c maps to c+d.
        choices = []
        for d in range(-max_shift, max_shift + 1):
            moved = {c + d for c in bot if 0 <= c + d < w}
            overlap = len(moved & top)
            mismatch = len(moved ^ top)
            choices.append(((overlap, -mismatch, -abs(d)), d, moved))
        _, d, moved_bot = max(choices, key=lambda item: item[0])

        top_right = max(top, default=-1)
        bot_right = max(moved_bot, default=-1)
        if bot_right > top_right:
            # Lower pattern extends farther right; color its unmatched tail in upper.
            for c in moved_bot:
                if c > top_right and c not in top:
                    out[ur][c] = 1
        elif top_right > bot_right:
            # Upper pattern extends farther right; map its tail back to lower.
            for c in top:
                lower_c = c - d
                if c > bot_right and 0 <= lower_c < w and lower_c not in bot:
                    out[lr][lower_c] = 1
    return out
